/**
 * SenseNova U1.6 Lite text-to-image tool with 6.8 Flash visual checks.
 *
 * The model is an image-generation model served by an OpenAI-compatible
 * `/v1/images/generations` endpoint; it has no chat-completions route. This
 * plugin exposes it to every DSH agent (root and subagents) as one tool,
 * downloads the generated bytes, saves them in the session working directory,
 * and returns absolute paths plus ready-to-use Markdown.
 */

import { randomUUID } from 'node:crypto'
import { mkdir, writeFile } from 'node:fs/promises'
import { isAbsolute, join, resolve } from 'node:path'
import z from '@deepseek-ai/schemastery'
import { defineTool, ToolArgsError } from '@deepseek-ai/dsh-tools'

export const name = 'sensenova-image'
export const inject = ['tools', 'workingDirectory']

const DEFAULT_BASE_URL = 'https://token.sensenova.cn/v1'
const DEFAULT_MODEL = 'sensenova-u1.6-lite'
const VISION_MODEL = 'sensenova-6.8-flash'
const DEFAULT_API_KEY_ENV = 'SENSENOVA_API_KEY'
/** Optional user-supplied key; when configured it outranks `apiKeyEnv`. */
const USER_API_KEY_ENV = 'SENSENOVA_IMAGE_API_KEY'
const DEFAULT_OUTPUT_DIR = 'generated-images'
const DEFAULT_REQUEST_TIMEOUT_MS = 300_000
const TOOL_TIMEOUT_MS = 360_000
const VISION_TIMEOUT_MS = 120_000
const MAX_IMAGES = 4

const OUTPUT_FORMATS = {
  png: 'image/png',
  jpeg: 'image/jpeg',
  webp: 'image/webp',
}

/**
 * Live plugin configuration.
 *
 * Request defaults are volatile: the settings page writes them into the active
 * profile entry, and the tool reads them at call time. `apiKeyEnv`, `baseURL`
 * and `requestTimeoutMs` stay ordinary because they are deployment wiring, not
 * per-image choices.
 */
export const Config = z.object({
  apiKeyEnv: z.string().default(DEFAULT_API_KEY_ENV),
  baseURL: z.string().default(DEFAULT_BASE_URL),
  model: z.string().default(DEFAULT_MODEL).volatile(),
  size: z.string().default('2048x2048').volatile(),
  n: z.number().step(1).min(1).max(MAX_IMAGES).default(1).volatile(),
  watermark: z.boolean().default(false).volatile(),
  prompt_extend: z.boolean().default(true).volatile(),
  verify: z.boolean().default(true).volatile(),
  output_format: z.string().default('png').volatile(),
  outputDir: z.string().default(DEFAULT_OUTPUT_DIR).volatile(),
  requestTimeoutMs: z.number().default(DEFAULT_REQUEST_TIMEOUT_MS),
})

function textConfig(config, key, fallback) {
  const value = config?.[key]
  return typeof value === 'string' && value.trim() !== '' ? value.trim() : fallback
}

function numberConfig(config, key, fallback) {
  const value = config?.[key]
  return typeof value === 'number' && Number.isFinite(value) && value > 0 ? value : fallback
}

/** Read a volatile Config field, or a plain value in tests and older profiles. */
function liveConfig(config, key, fallback) {
  const field = config?.[key]
  const value = field !== null && typeof field === 'object' && typeof field.get === 'function'
    ? field.get()
    : field
  return value === undefined ? fallback : value
}

/** Turn a prompt or requested filename into a short, filesystem-safe stem. */
function safeStem(value, fallback) {
  const cleaned = String(value ?? '')
    .normalize('NFKC')
    .replace(/[^\p{L}\p{N}]+/gu, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 40)
  return cleaned === '' ? fallback : cleaned
}

/** Validate the API's size syntax before spending a request. */
function normalizeSize(raw) {
  const size = typeof raw === 'string' && raw.trim() !== '' ? raw.trim() : '2048x2048'
  if (/^(2k|4k)$/i.test(size)) return size.toUpperCase()
  const match = /^(\d{3,4})x(\d{3,4})$/i.exec(size)
  if (match === null) {
    throw new ToolArgsError(['size must be "2K", "4K", or WIDTHxHEIGHT such as "2048x2048"'])
  }
  const width = Number(match[1])
  const height = Number(match[2])
  const problems = []
  if (width < 512 || width > 4096 || height < 512 || height > 4096) {
    problems.push('width and height must be between 512 and 4096')
  }
  if (width % 32 !== 0 || height % 32 !== 0) problems.push('width and height must be multiples of 32')
  if (Math.max(width, height) / Math.min(width, height) > 3) problems.push('the aspect ratio cannot exceed 3:1')
  if (problems.length > 0) throw new ToolArgsError(problems)
  return `${width}x${height}`
}

/** Resolve one credential reference from the DSH credential store, then the launch environment. */
async function resolveKeyRef(ctx, ref) {
  const credentials = ctx.get('credentials')
  if (credentials !== undefined) {
    const hit = await credentials.resolve(ref)
    if (hit !== undefined && typeof hit.value === 'string' && hit.value.trim() !== '') return hit.value.trim()
  }
  const fromEnvironment = process.env[ref]
  if (typeof fromEnvironment === 'string' && fromEnvironment.trim() !== '') return fromEnvironment.trim()
  return undefined
}

/**
 * Resolve the API key. A key saved on the settings page under
 * `SENSENOVA_IMAGE_API_KEY` always wins; without one, the configured
 * `apiKeyEnv` (default `SENSENOVA_API_KEY`) remains the fallback.
 */
async function resolveApiKey(ctx, ref) {
  const custom = await resolveKeyRef(ctx, USER_API_KEY_ENV)
  if (custom !== undefined) return custom
  const fallback = await resolveKeyRef(ctx, ref)
  if (fallback !== undefined) return fallback
  throw new Error(
    `sensenova_generate_image: no API key; set ${USER_API_KEY_ENV} in Settings, `
    + `or configure ${ref} in the DSH credential store / environment`,
  )
}

/** POST one generation request, combining the tool's cancellation with a request timeout. */
async function requestGeneration({ baseURL, apiKey, body, signal, timeoutMs }) {
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(new Error(`request timed out after ${timeoutMs} ms`)), timeoutMs)
  const forwardAbort = () => controller.abort(signal.reason)
  signal.addEventListener('abort', forwardAbort, { once: true })
  try {
    const response = await fetch(`${baseURL.replace(/\/+$/u, '')}/images/generations`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
      signal: controller.signal,
    })
    const raw = await response.text()
    let payload
    try {
      payload = raw === '' ? undefined : JSON.parse(raw)
    } catch {
      payload = undefined
    }
    if (!response.ok) {
      const detail = payload?.error?.message ?? payload?.message ?? raw.slice(0, 500)
      throw new Error(`sensenova_generate_image: HTTP ${response.status} from /images/generations: ${detail}`)
    }
    if (payload === undefined || !Array.isArray(payload.data) || payload.data.length === 0) {
      throw new Error('sensenova_generate_image: the API returned no image data')
    }
    return payload
  } finally {
    clearTimeout(timer)
    signal.removeEventListener('abort', forwardAbort)
  }
}

/** Read one image's bytes from the API's URL or inline Base64 form. */
async function readImageBytes(item, signal) {
  if (typeof item.b64_json === 'string' && item.b64_json !== '') {
    return Buffer.from(item.b64_json, 'base64')
  }
  if (typeof item.url === 'string' && item.url !== '') {
    const response = await fetch(item.url, { signal })
    if (!response.ok) {
      throw new Error(
        `sensenova_generate_image: could not download the generated image (HTTP ${response.status}); `
        + `the temporary URL is ${item.url}`,
      )
    }
    return Buffer.from(await response.arrayBuffer())
  }
  throw new Error('sensenova_generate_image: the API returned neither url nor b64_json')
}

/** Extract the JSON verdict from a vision reply, tolerating code fences and prose. */
function parseVerdict(content) {
  const text = typeof content === 'string' ? content.trim() : ''
  if (text === '') return undefined
  const fenced = text.replace(/^```(?:json)?\s*/iu, '').replace(/\s*```$/u, '')
  try { return JSON.parse(fenced) } catch (_failure) { /* fall through */ }
  const start = fenced.indexOf('{')
  const end = fenced.lastIndexOf('}')
  if (start !== -1 && end > start) {
    try { return JSON.parse(fenced.slice(start, end + 1)) } catch (_failure) { /* fall through */ }
  }
  return undefined
}

function normalizeVerdict(value) {
  return value === 'pass' || value === 'warn' || value === 'fail' ? value : 'warn'
}

/**
 * Ask `sensenova-6.8-flash` to check one generated image against the prompt.
 * The key and base URL are the same as the image call; a failure is reported
 * in the result instead of discarding the image.
 */
async function verifyImage({ baseURL, apiKey, prompt, imageUrl, signal, timeoutMs }) {
  const instruction = [
    '你是严格的图像质检员。只输出 JSON，不要输出其他文字。',
    `用户要求：${prompt}`,
    '请核对这张生成图是否满足要求，检查主体、颜色、构图、文字和明显瑕疵。',
    '输出 JSON：{"verdict":"pass|warn|fail","summary":"一句话结论","issues":["问题1"]}。',
  ].join('\n')
  const body = {
    model: VISION_MODEL,
    messages: [{
      role: 'user',
      content: [
        { type: 'text', text: instruction },
        { type: 'image_url', image_url: { url: imageUrl } },
      ],
    }],
    max_tokens: 800,
    temperature: 0.1,
  }
  const controller = new AbortController()
  const timer = setTimeout(() => controller.abort(new Error(`vision request timed out after ${timeoutMs} ms`)), timeoutMs)
  const forwardAbort = () => controller.abort(signal.reason)
  signal.addEventListener('abort', forwardAbort, { once: true })
  try {
    const response = await fetch(`${baseURL.replace(/\/+$/u, '')}/chat/completions`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
      signal: controller.signal,
    })
    const raw = await response.text()
    let payload
    try {
      payload = raw === '' ? undefined : JSON.parse(raw)
    } catch (_failure) {
      payload = undefined
    }
    if (!response.ok) {
      const detail = payload?.error?.message ?? payload?.message ?? raw.slice(0, 300)
      throw new Error(`HTTP ${response.status}: ${detail}`)
    }
    const content = payload?.choices?.[0]?.message?.content
    const parsed = parseVerdict(content)
    if (parsed === undefined) {
      return {
        model: VISION_MODEL,
        status: 'error',
        summary: String(content ?? 'empty vision response').slice(0, 500),
      }
    }
    return {
      model: VISION_MODEL,
      status: normalizeVerdict(parsed.verdict),
      summary: typeof parsed.summary === 'string' ? parsed.summary.slice(0, 500) : '',
      issues: Array.isArray(parsed.issues)
        ? parsed.issues.filter(issue => typeof issue === 'string').slice(0, 8)
        : [],
    }
  } catch (error) {
    return {
      model: VISION_MODEL,
      status: 'error',
      summary: error instanceof Error ? error.message : String(error),
    }
  } finally {
    clearTimeout(timer)
    signal.removeEventListener('abort', forwardAbort)
  }
}

export function apply(ctx, config) {
  const baseURL = textConfig(config, 'baseURL', DEFAULT_BASE_URL)
  const apiKeyEnv = textConfig(config, 'apiKeyEnv', DEFAULT_API_KEY_ENV)
  const requestTimeoutMs = numberConfig(config, 'requestTimeoutMs', DEFAULT_REQUEST_TIMEOUT_MS)

  // This bundle ships its own settings section; keep the schema-derived form off.
  ctx.inject(['settings'], (settingsCtx) => {
    settingsCtx.effect(() => settingsCtx.settings.configure({ auto: false }, ctx.fiber))
  })

  ctx.tools.register(defineTool({
    name: 'sensenova_generate_image',
    description:
      'Generate one or more images from a text prompt with SenseNova U1.6 Lite (sensenova-u1.6-lite). '
      + 'After saving each image, SenseNova 6.8 Flash (sensenova-6.8-flash) checks it against the prompt and '
      + 'reports pass/warn/fail plus issues; a failed check does not discard the image. '
      + 'The image model is an image-generation model, not a chat model. Images are downloaded and saved in the '
      + 'session working directory; the result contains each absolute path, byte size, temporary URL, ready-to-use '
      + 'Markdown, and the visual-check result. Put the returned Markdown in your reply so the user can see the '
      + 'image. Use this tool for any text-to-image request, such as illustrations, posters, product shots, or '
      + 'infographics. Size, n, watermark, prompt_extend, verify, and output_format default to the values on the '
      + 'plugin settings page; explicit parameters override them.',
    parameters: {
      prompt: {
        type: 'string',
        required: true,
        description: 'Image description. Chinese and English are both supported; longer, more specific prompts work well.',
      },
      size: {
        type: 'string',
        description: 'Output size: "2K", "4K", or WIDTHxHEIGHT. Width and height must be 512-4096, multiples of 32, and no more than 3:1 apart. Omit to use the settings page default.',
      },
      n: {
        type: 'integer',
        description: `Number of images to generate, 1-${MAX_IMAGES}. Omit to use the settings page default.`,
      },
      watermark: {
        type: 'boolean',
        description: 'Add the provider watermark. Omit to use the settings page default.',
      },
      prompt_extend: {
        type: 'boolean',
        description: 'Let the provider expand and refine the prompt automatically. Omit to use the settings page default.',
      },
      verify: {
        type: 'boolean',
        description: 'Check each generated image with sensenova-6.8-flash. Omit to use the settings page default.',
      },
      output_format: {
        type: 'string',
        enum: ['png', 'jpeg', 'webp'],
        description: 'Saved image format. Omit to use the settings page default.',
      },
      filename: {
        type: 'string',
        description: 'Optional base name for the saved file; the extension and a uniqueness suffix are added automatically.',
      },
    },
    output: {
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          model: { type: 'string', required: true },
          prompt: { type: 'string', required: true },
          size: { type: 'string', required: true },
          images: {
            type: 'array',
            required: true,
            items: {
              type: 'object',
              additionalProperties: false,
              properties: {
                path: { type: 'string', required: true },
                bytes: { type: 'integer', required: true },
                markdown: { type: 'string', required: true },
                url: { type: 'string' },
                verification: {
                  type: 'object',
                  additionalProperties: false,
                  properties: {
                    model: { type: 'string', required: true },
                    status: { type: 'string', required: true, enum: ['pass', 'warn', 'fail', 'error'] },
                    summary: { type: 'string' },
                    issues: { type: 'array', items: { type: 'string' } },
                  },
                },
              },
            },
          },
        },
      },
      render(_args, value) {
        const lines = [
          `Generated ${value.images.length} image(s) with ${value.model} at ${value.size}.`,
        ]
        for (const image of value.images) {
          lines.push(`- ${image.path} (${image.bytes} bytes)`)
          lines.push(`  Markdown: ${image.markdown}`)
          if (image.url !== undefined) lines.push(`  Temporary URL (24h): ${image.url}`)
          if (image.verification !== undefined) {
            lines.push(`  Visual check (${image.verification.model}): ${image.verification.status} — ${image.verification.summary ?? ''}`)
            if (Array.isArray(image.verification.issues) && image.verification.issues.length > 0) {
              lines.push(`  Issues: ${image.verification.issues.join('; ')}`)
            }
          }
        }
        lines.push('Include the Markdown line in your reply so the user can see the image.')
        return [{ type: 'text', text: lines.join('\n') }]
      },
    },
    timeoutMs: TOOL_TIMEOUT_MS,
    async execute(args, exec) {
      exec.signal.throwIfAborted()

      const prompt = args.prompt.trim()
      if (prompt === '') throw new ToolArgsError(['prompt must not be blank'])

      const selectedModel = DEFAULT_MODEL
      const verify = args.verify ?? liveConfig(config, 'verify', true)

      const size = normalizeSize(args.size ?? liveConfig(config, 'size', '2048x2048'))
      const n = args.n ?? liveConfig(config, 'n', 1)
      if (!Number.isInteger(n) || n < 1 || n > MAX_IMAGES) {
        throw new ToolArgsError([`n must be an integer from 1 to ${MAX_IMAGES}`])
      }
      const format = args.output_format ?? liveConfig(config, 'output_format', 'png')
      if (!Object.hasOwn(OUTPUT_FORMATS, format)) {
        throw new ToolArgsError(['output_format must be png, jpeg, or webp'])
      }

      const apiKey = await resolveApiKey(ctx, apiKeyEnv)
      const body = {
        model: selectedModel,
        prompt,
        n,
        size,
        output_format: format,
        response_format: 'url',
        watermark: args.watermark ?? liveConfig(config, 'watermark', false),
        prompt_extend: args.prompt_extend ?? liveConfig(config, 'prompt_extend', true),
      }

      const payload = await requestGeneration({
        baseURL,
        apiKey,
        body,
        signal: exec.signal,
        timeoutMs: requestTimeoutMs,
      })

      const session = exec.agent?.session
      const cwd = session !== undefined
        ? ctx.workingDirectory.get(session)
        : ctx.workingDirectory.defaultDirectory
      const outputDirectory = liveConfig(config, 'outputDir', DEFAULT_OUTPUT_DIR) || DEFAULT_OUTPUT_DIR
      const directory = isAbsolute(outputDirectory) ? outputDirectory : resolve(cwd, outputDirectory)
      await mkdir(directory, { recursive: true })

      const stem = safeStem(args.filename ?? prompt, 'image')
      const stamp = new Date().toISOString().replace(/[:.]/gu, '-')
      const images = []
      for (const [index, item] of payload.data.entries()) {
        const bytes = await readImageBytes(item, exec.signal)
        const path = join(directory, `${stamp}-${stem}-${index + 1}-${randomUUID().slice(0, 8)}.${format}`)
        await writeFile(path, bytes)
        const image = {
          path,
          bytes: bytes.byteLength,
          markdown: `![SenseNova image](<${path}>)`,
          ...(typeof item.url === 'string' && item.url !== '' ? { url: item.url } : {}),
        }
        if (verify) {
          const imageUrl = typeof item.url === 'string' && item.url !== ''
            ? item.url
            : `data:${OUTPUT_FORMATS[format]};base64,${bytes.toString('base64')}`
          image.verification = await verifyImage({
            baseURL,
            apiKey,
            prompt,
            imageUrl,
            signal: exec.signal,
            timeoutMs: VISION_TIMEOUT_MS,
          })
        }
        images.push(image)
      }

      return {
        model: selectedModel,
        prompt,
        size: typeof payload.size === 'string' && payload.size !== '' ? payload.size : size,
        images,
      }
    },
  }))

}
